// Identity tables (data-model.md sections 3.1-3.4): players, identities, refresh_tokens, profiles.
// Ids are UUIDv7 generated by the application. Enums are text + CHECK (data-model.md section 1).

import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { hexBytea } from "./types.ts";

/** Account row. A guest is a player whose only identity is a recovery code. */
export const players = pgTable(
  "players",
  {
    id: uuid("id").primaryKey(),
    status: text("status").notNull().default("active"),
    isGuest: boolean("is_guest").notNull().default(true),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("players_status_check", sql`${t.status} in ('active', 'deleted')`),
    // Retention purge (inactive guests, data-model.md section 5) scans by last_seen_at.
    index("players_last_seen_at_idx").on(t.lastSeenAt),
  ],
);

/** Login methods of a player. MVP: `recovery_code` only (subject = hex HMAC-SHA256 of the code under the pepper). */
export const identities = pgTable(
  "identities",
  {
    id: uuid("id").primaryKey(),
    playerId: uuid("player_id")
      .notNull()
      .references(() => players.id, { onDelete: "cascade" }),
    provider: text("provider").notNull(),
    subject: text("subject").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
  },
  (t) => [
    check("identities_provider_check", sql`${t.provider} in ('recovery_code', 'discord', 'google', 'github')`),
    // Recovery lookup is by (provider, subject); uniqueness stops two players sharing a code hash.
    uniqueIndex("identities_provider_subject_uq").on(t.provider, t.subject),
    // Cascade delete and "identities of this player".
    index("identities_player_id_idx").on(t.playerId),
  ],
);

/** Rotating opaque refresh tokens, stored only as HMAC-SHA256 digests (security.md section 3). */
export const refreshTokens = pgTable(
  "refresh_tokens",
  {
    id: uuid("id").primaryKey(),
    playerId: uuid("player_id")
      .notNull()
      .references(() => players.id, { onDelete: "cascade" }),
    familyId: uuid("family_id").notNull(),
    tokenHash: hexBytea("token_hash").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
    replacedBy: uuid("replaced_by"),
    replacedAt: timestamp("replaced_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    revokeReason: text("revoke_reason"),
  },
  (t) => [
    check(
      "refresh_tokens_revoke_reason_check",
      sql`${t.revokeReason} is null or ${t.revokeReason} in ('logout', 'reuse_detected', 'superseded', 'player_deleted', 'admin', 'recovered')`,
    ),
    // Every refresh looks the presented token up by its digest.
    uniqueIndex("refresh_tokens_token_hash_uq").on(t.tokenHash),
    // Cascade delete and "revoke every family of a player" (recovery).
    index("refresh_tokens_player_id_idx").on(t.playerId),
    // Family revoke on reuse detection and the successor lookup of the grace window.
    index("refresh_tokens_family_id_idx").on(t.familyId),
    // Daily retention delete of expired rows.
    index("refresh_tokens_expires_at_idx").on(t.expiresAt),
  ],
);

/** Per-player profile that persists across Contracts. One row per player (created with the player). */
export const profiles = pgTable(
  "profiles",
  {
    playerId: uuid("player_id")
      .primaryKey()
      .references(() => players.id, { onDelete: "cascade" }),
    displayName: text("display_name").notNull(),
    tenureLevel: smallint("tenure_level").notNull().default(0),
    tenurePoints: bigint("tenure_points", { mode: "number" }).notNull().default(0),
    commendations: integer("commendations").notNull().default(0),
    lifetimeLumens: doublePrecision("lifetime_lumens").notNull().default(0),
    lifetimePlotsPolished: integer("lifetime_plots_polished").notNull().default(0),
    cosmeticsOwned: text("cosmetics_owned")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    equippedCosmetics: jsonb("equipped_cosmetics")
      .$type<Record<string, string>>()
      .notNull()
      .default(sql`'{}'::jsonb`),
    /** Optimistic concurrency for REST edits versus in-room flushes. */
    version: integer("version").notNull().default(0),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("profiles_commendations_check", sql`${t.commendations} >= 0`),
    check("profiles_equipped_cosmetics_size_check", sql`pg_column_size(${t.equippedCosmetics}) <= 1024`),
  ],
);

export type PlayerRow = typeof players.$inferSelect;
export type ProfileRow = typeof profiles.$inferSelect;
